// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address depositor, uint128 amount) public {
        vm.assume(depositor != address(0));
        uint256 amt = bound(uint256(amount), 1, 1 ether);

        vm.deal(depositor, amt);
        vm.prank(depositor);
        c.addToBalance{value: amt}();

        uint256 before = address(c).balance;

        vm.prank(depositor);
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == before - amt);
        } else {
            assertTrue(address(c).balance == before);
        }
    }
}
